--
-- Table structure for table `settings`
--

DROP TABLE IF EXISTS `settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `settings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `label` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` text COLLATE utf8mb4_unicode_ci,
  `type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'text',
  `group` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'general',
  `updated_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `settings_key_unique` (`key`),
  KEY `settings_updated_by_foreign` (`updated_by`),
  CONSTRAINT `settings_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `settings`
--

LOCK TABLES `settings` WRITE;
/*!40000 ALTER TABLE `settings` DISABLE KEYS */;
INSERT INTO `settings` VALUES (1,'app_name','Nama Aplikasi','Pinisi Kendari','text','general',NULL,NULL,NULL),(2,'app_logo','Logo Aplikasi',NULL,'image','general',NULL,NULL,NULL),(3,'app_description','Deskripsi Aplikasi','Platform booking trip kapal #1 di kendari!.','textarea','general',NULL,NULL,NULL),(4,'hero_badge','Hero Badge Text','100+ jadwal tersedia hari ini','text','landing',NULL,NULL,NULL),(5,'hero_title','Hero Title','Jelajahi Surga di Kendari tanpa batas','text','landing',NULL,NULL,NULL),(6,'hero_subtitle','Hero Subtitle','Pesan tiket trip kapal dengan mudah dan nikmati liburanmu diatas kapal pinisi.','textarea','landing',NULL,NULL,NULL),(7,'hero_image','Hero Image',NULL,'image','landing',NULL,NULL,NULL),(8,'hero_cta_text','Hero CTA Text','Cari Jadwal','text','landing',NULL,NULL,NULL),(9,'hero_stats','Hero Statistics (JSON)','[{\"value\":\"50K+\",\"label\":\"Penumpang Puas\"},{\"value\":\"4.9\",\"label\":\"Rating Pengguna\"},{\"value\":\"15+\",\"label\":\"Rute Tersedia\"}]','json','landing',NULL,NULL,NULL),(10,'landing_features','Fitur Unggulan (JSON)','[{\"icon\":\"QrCode\",\"title\":\"Digital Boarding Pass\",\"description\":\"Tidak perlu cetak tiket. Cukup tunjukkan QR code dari handphone Anda saat boarding.\"},{\"icon\":\"Shield\",\"title\":\"Jaminan Uang Kembali\",\"description\":\"Refund 100% jika pembatalan oleh operator.\"},{\"icon\":\"Ship\",\"title\":\"Armada Premium\",\"description\":\"Kapal modern dengan fasilitas VIP terbaik.\"},{\"icon\":\"Map\",\"title\":\"Real-time Tracking\",\"description\":\"Pantau posisi kapal secara langsung melalui GPS tracking di aplikasi kami.\"}]','json','landing',NULL,NULL,NULL),(11,'landing_testimonials','Testimoni Pelanggan (JSON)','[{\"name\":\"Andi Saputra\",\"text\":\"Booking cepat, langsung dapat e-ticket. Praktis buat liburan keluarga!\",\"avatar\":\"\\ud83d\\udc68\\u200d\\ud83d\\udcbc\"},{\"name\":\"Siti Noor\",\"text\":\"Harga transparan dan pelayanannya sangat memuaskan. Recommended!\",\"avatar\":\"\\ud83d\\udc69\\u200d\\ud83e\\uddb0\"},{\"name\":\"Budi Santoso\",\"text\":\"Kapalnya bersih dan tepat waktu. Pengalaman yang luar biasa.\",\"avatar\":\"\\ud83d\\udc68\\u200d\\ud83d\\udd2c\"},{\"name\":\"Dewi Lestari\",\"text\":\"Sangat membantu untuk pesan tiket antar pulau di Sulawesi.\",\"avatar\":\"\\ud83d\\udc69\\u200d\\ud83c\\udf93\"}]','json','landing',NULL,NULL,NULL),(12,'landing_cta','CTA Bottom Section (JSON)','{\"headline\":\"Siap Memulai Petualanganmu?\",\"subheadline\":\"Pesan tiketmu sekarang dan nikmati keindahan alam Sulawesi yang memukau\",\"primary_button\":\"Pesan Tiket Sekarang\",\"secondary_button\":\"Hubungi Kami\"}','json','landing',NULL,NULL,NULL),(13,'landing_social_proof_title','Judul Social Proof','Dipercaya oleh operator terbaik di Indonesia','text','landing',NULL,NULL,NULL),(14,'landing_social_proof_clients','Daftar Klien/Operator (JSON)','[{\"name\":\"Pelni\",\"logo\":\"\\ud83d\\udea2\"},{\"name\":\"ASDP\",\"logo\":\"\\u26f4\\ufe0f\"},{\"name\":\"Dharma Lautan\",\"logo\":\"\\ud83d\\udef3\\ufe0f\"},{\"name\":\"Express Bahari\",\"logo\":\"\\ud83d\\udea4\"},{\"name\":\"Sindo Ferry\",\"logo\":\"\\u2693\"},{\"name\":\"Blue Sea Jet\",\"logo\":\"\\ud83c\\udf0a\"}]','json','landing',NULL,NULL,NULL),(15,'contact_email','Email Kontak','info@kapaltrip.id','text','contact',NULL,NULL,NULL),(16,'contact_whatsapp','WhatsApp Kontak','6281234567890','text','contact',NULL,NULL,NULL),(17,'social_instagram','Link Instagram','https://instagram.com/kapaltrip','text','contact',NULL,NULL,NULL),(18,'social_facebook','Link Facebook','https://facebook.com/kapaltrip','text','contact',NULL,NULL,NULL);
/*!40000 ALTER TABLE `settings` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `ships`
--

DROP TABLE IF EXISTS `ships`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ships` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `branch_id` bigint unsigned NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `capacity` int NOT NULL,
  `status` enum('ACTIVE','MAINTENANCE','INACTIVE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `description` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
